// Load the invoice images and the purchase-order list. One item per invoice.
const fs = require('fs');
const path = require('path');
const base = $env.EP04_DIR;
const pos = fs.readFileSync(path.join(base, 'data', 'purchase-orders.csv'), 'utf8')
  .trim().split('\n').slice(1).map((l) => {
    const [po_number, vendor, amount] = l.split(',');
    return { po_number, vendor, amount: Number(amount) };
  });
const dir = path.join(base, 'data', 'invoices');
return fs.readdirSync(dir).filter((f) => f.endsWith('.png')).sort().map((f) => ({
  json: {
    file: f,
    image: 'data:image/png;base64,' + fs.readFileSync(path.join(dir, f)).toString('base64'),
    pos,
  },
}));

// A vision model reads every invoice image into strict JSON.
// If a field is not on the document, it must say null — never guess.
const https = require('https');

const read = (payload) => new Promise((resolve, reject) => {
  const body = JSON.stringify(payload);
  const req = https.request({
    hostname: 'fal.run', path: '/fal-ai/any-llm/vision', method: 'POST',
    headers: {
      'Authorization': 'Key ' + $env.FAL_KEY,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  }, (res) => {
    let data = '';
    res.on('data', (c) => (data += c));
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

const out = [];
for (const item of $input.all()) {
  const t = item.json;
  const res = await read({
    model: 'google/gemini-flash-1.5',
    system_prompt:
      'You extract structured data from invoice images. Reply with ONLY JSON: ' +
      '{"vendor": str, "invoice_number": str, "invoice_date": "YYYY-MM-DD", ' +
      '"total": number, "currency": "USD"|..., "po_number": str|null}. ' +
      'If a field is not on the document, use null. Never guess a PO number.',
    prompt: 'Extract the fields from this invoice.',
    image_url: t.image,
  });
  let fields;
  try { fields = JSON.parse((res.output ?? '').replace(/```json|```/g, '').trim()); }
  catch { fields = { vendor: null, invoice_number: null, total: null, po_number: null, unreadable: true }; }
  out.push({ json: { file: t.file, pos: t.pos, ...fields } });
}
return out;

// The gate. An invoice only gets approved if it matches a real PO,
// to the cent, and hasn't been paid before. Everything else → a human.
const fs = require('fs');
const path = require('path');
const dir = path.join($env.EP04_DIR, 'out');
fs.mkdirSync(dir, { recursive: true });

const seen = new Set();
const approved = [];
const flagged = [];
for (const { json: r } of $input.all()) {
  const id = r.vendor + '|' + r.invoice_number;
  const po = (r.pos ?? []).find((p) => p.po_number === r.po_number);
  const flag =
    r.unreadable ? 'UNREADABLE — human review' :
    seen.has(id) ? 'DUPLICATE — already processed ' + r.invoice_number :
    !r.po_number ? 'NO PO — nobody ordered this' :
    !po ? 'UNKNOWN PO — ' + r.po_number + ' is not in the system' :
    Math.abs(r.total - po.amount) > 0.01
      ? 'AMOUNT MISMATCH — invoice $' + r.total + ' vs PO $' + po.amount :
    null;
  seen.add(id);
  const { pos, image, ...rec } = r;
  (flag ? flagged : approved).push(flag ? { ...rec, flag } : rec);
}
fs.writeFileSync(path.join(dir, 'approved.json'), JSON.stringify(approved, null, 2));
fs.writeFileSync(path.join(dir, 'flagged.json'), JSON.stringify(flagged, null, 2));
const summary = {
  invoices: approved.length + flagged.length,
  approved: approved.length,
  flagged: flagged.length,
  approved_value: '$' + approved.reduce((n, a) => n + a.total, 0).toFixed(2),
};
fs.writeFileSync(path.join(dir, 'summary.json'), JSON.stringify(summary, null, 2));
return [{ json: summary }];
